{"__advancedHuntingSettings":true,"query":"let exploitable = DeviceTvmSoftwareVulnerabilitiesKB | where IsExploitAvailable == 1 | distinct CveId;
let v = DeviceTvmSoftwareVulnerabilities | where VulnerabilitySeverityLevel in ("Critical", "High") | where CveId in (exploitable);
v | summarize Value = dcount(CveId) | extend Metric = "Exploitable CVEs", Description = "Critical/High CVEs with public exploit code", Sort = 0
| union (v | summarize Value = dcount(DeviceId) | extend Metric = "Exposed devices", Description = "Devices exposed to those exploitable CVEs", Sort = 1)
| order by Sort asc
| project Metric, Value, Description","selectedWorkspaceIds":["e34d562e-ef12-4c4e-9bc0-7c6ae357c015"]}

{"__advancedHuntingSettings":true,"query":"let di = DeviceInfo | summarize arg_max(Timestamp, OnboardingStatus) by DeviceId;
di | summarize Value = round(100.0 * dcountif(DeviceId, OnboardingStatus == "Onboarded") / dcount(DeviceId), 1) | extend Metric = "Coverage %", Description = "Share of known devices onboarded to Defender", Sort = 0
| union (di | summarize Value = todouble(dcountif(DeviceId, OnboardingStatus == "Onboarded")) | extend Metric = "Onboarded", Description = "Devices reporting to Defender for Endpoint", Sort = 1)
| union (di | summarize Value = todouble(dcount(DeviceId)) | extend Metric = "Known devices", Description = "All devices seen (onboarded + not onboarded)", Sort = 2)
| order by Sort asc
| project Metric, Value, Description","selectedWorkspaceIds":["e34d562e-ef12-4c4e-9bc0-7c6ae357c015"]}
